import { execFileSync } from 'node:child_process'
import { writeFileSync } from 'node:fs'
const queries={
  "TABLE_SCHEMAS": "SELECT m.name AS table_name, group_concat(pi.name || ':' || pi.type, ' | ') AS columns FROM sqlite_master m,pragma_table_info(m.name) pi WHERE m.type='table' AND (m.name IN ('inventory_operations','critical_operations','inventory_movements','inventory_stock','inventory_stock_checks','inventory_stocktake_items','inventory_reservations','catalog_variants','catalog_products','order_items','inventory_operation_evidence','inventory_operation_request_fingerprints','inventory_lifecycle_events','inventory_lifecycle_operations','inventory_transfer_items','inventory_stocktake_sessions','activity_log')) GROUP BY m.name ORDER BY m.name",
  "PRODUCT_MATCHES": "SELECT id,name,category,gender_scope,is_active,created_at FROM catalog_products p WHERE (UPPER(COALESCE(p.name,'')) LIKE '%БАЯН%' OR UPPER(COALESCE(p.name,'')) LIKE '%НӘЗІК%' OR UPPER(COALESCE(p.name,'')) LIKE '%НАЗЫК%' OR UPPER(COALESCE(p.name,'')) LIKE '%НАЗИК%') ORDER BY name,id",
  "MALE_VARIANTS": "SELECT p.id AS product_id,p.name AS product_name,p.gender_scope AS product_gender_scope,v.id AS variant_id,v.external_id,v.is_active,v.gender,v.color,v.material,v.length,v.size_label,v.stock_position_id,v.created_at,v.updated_at FROM catalog_variants v JOIN catalog_products p ON p.id=v.product_id WHERE (UPPER(COALESCE(p.name,'')) LIKE '%БАЯН%' OR UPPER(COALESCE(p.name,'')) LIKE '%НӘЗІК%' OR UPPER(COALESCE(p.name,'')) LIKE '%НАЗЫК%' OR UPPER(COALESCE(p.name,'')) LIKE '%НАЗИК%') AND UPPER(TRIM(COALESCE(v.gender,''))) IN ('МУЖ','М','MALE') ORDER BY p.name,v.id LIMIT 500",
  "OTHER_GENDER_VARIANT_SUMMARY": "SELECT p.id AS product_id,p.name AS product_name,COALESCE(v.gender,'(null)') AS gender,v.is_active AS active,COUNT(*) AS variant_count FROM catalog_variants v JOIN catalog_products p ON p.id=v.product_id WHERE (UPPER(COALESCE(p.name,'')) LIKE '%БАЯН%' OR UPPER(COALESCE(p.name,'')) LIKE '%НӘЗІК%' OR UPPER(COALESCE(p.name,'')) LIKE '%НАЗЫК%' OR UPPER(COALESCE(p.name,'')) LIKE '%НАЗИК%') GROUP BY p.id,gender,v.is_active ORDER BY p.name,gender",
  "MALE_VARIANT_CURRENT_STOCK": "WITH sources(src) AS (VALUES ('warehouse'),('boutique')), v AS (SELECT v.*,p.name AS product_name FROM catalog_variants v JOIN catalog_products p ON p.id=v.product_id WHERE (UPPER(COALESCE(p.name,'')) LIKE '%БАЯН%' OR UPPER(COALESCE(p.name,'')) LIKE '%НӘЗІК%' OR UPPER(COALESCE(p.name,'')) LIKE '%НАЗЫК%' OR UPPER(COALESCE(p.name,'')) LIKE '%НАЗИК%') AND UPPER(TRIM(COALESCE(v.gender,''))) IN ('МУЖ','М','MALE')) SELECT v.id AS variant_id,v.product_name,v.is_active AS variant_active,v.gender,v.color,v.material,v.length,v.size_label AS size,sources.src AS source,COALESCE(s.quantity,0) AS physical,COALESCE(s.reserved_quantity,0) AS cached_reserved,s.id AS stock_id,s.last_action,s.last_source_ref,s.created_at AS stock_created,s.updated_at AS stock_updated,(SELECT COALESCE(SUM(r.quantity),0) FROM inventory_reservations r WHERE r.inventory_source=sources.src AND r.variant_id=v.id AND r.status='active') AS actual_active_reserved,(SELECT COUNT(*) FROM inventory_movements m WHERE m.inventory_source=sources.src AND m.variant_id=v.id AND m.quantity_delta>0) AS positive_movement_count,(SELECT COUNT(*) FROM inventory_movements m WHERE m.inventory_source=sources.src AND m.variant_id=v.id AND m.movement_type IN ('arrival','return','transfer_in')) AS incoming_documents,(SELECT COUNT(*) FROM inventory_stock_checks c WHERE c.inventory_source=sources.src AND c.variant_id=v.id AND c.counted_quantity>0) AS positive_count_checks FROM v CROSS JOIN sources LEFT JOIN inventory_stock s ON s.variant_id=v.id AND s.inventory_source=sources.src ORDER BY v.product_name,v.id,sources.src LIMIT 1000",
  "MALE_RESERVATION_HISTORY": "SELECT r.id AS reservation_id,r.order_id,r.order_item_id,r.inventory_source AS source,r.variant_id,r.quantity AS qty,r.status,r.created_at AS reserved_at,r.updated_at AS last_changed,r.reference_type,r.unresolved_reason,o.order_date,o.created_at AS order_created_at,o.shipping_status,o.shipping_date,o.order_status,oi.stock_writeoff_status FROM inventory_reservations r LEFT JOIN orders o ON o.id=r.order_id LEFT JOIN order_items oi ON oi.id=r.order_item_id WHERE r.variant_id IN (SELECT v.id FROM catalog_variants v JOIN catalog_products p ON p.id=v.product_id WHERE (UPPER(COALESCE(p.name,'')) LIKE '%БАЯН%' OR UPPER(COALESCE(p.name,'')) LIKE '%НӘЗІК%' OR UPPER(COALESCE(p.name,'')) LIKE '%НАЗЫК%' OR UPPER(COALESCE(p.name,'')) LIKE '%НАЗИК%') AND UPPER(TRIM(COALESCE(v.gender,''))) IN ('МУЖ','М','MALE')) ORDER BY r.variant_id,r.created_at,r.id LIMIT 1000",
  "MALE_ORDER_ITEMS": "SELECT oi.id AS order_item_id,oi.variant_id,o.id AS order_id,o.order_date,o.created_at AS order_created,o.shipping_status,o.shipping_date,o.order_status,oi.quantity AS qty,oi.source_type AS source,oi.is_workshop,oi.stock_writeoff_status,oi.product_name_snapshot,oi.gender_snapshot,oi.color_snapshot,oi.material_snapshot,oi.length_snapshot,oi.size_snapshot,oi.created_at AS item_created,r.id AS reservation_id,r.status AS reserve_status FROM order_items oi JOIN orders o ON o.id=oi.order_id LEFT JOIN inventory_reservations r ON r.order_item_id=oi.id WHERE oi.variant_id IN (SELECT v.id FROM catalog_variants v JOIN catalog_products p ON p.id=v.product_id WHERE (UPPER(COALESCE(p.name,'')) LIKE '%БАЯН%' OR UPPER(COALESCE(p.name,'')) LIKE '%НӘЗІК%' OR UPPER(COALESCE(p.name,'')) LIKE '%НАЗЫК%' OR UPPER(COALESCE(p.name,'')) LIKE '%НАЗИК%') AND UPPER(TRIM(COALESCE(v.gender,''))) IN ('МУЖ','М','MALE')) OR ((UPPER(COALESCE(oi.product_name_snapshot,'')) LIKE '%БАЯН%' OR UPPER(COALESCE(oi.product_name_snapshot,'')) LIKE '%НӘЗІК%' OR UPPER(COALESCE(oi.product_name_snapshot,'')) LIKE '%НАЗЫК%') AND UPPER(TRIM(COALESCE(oi.gender_snapshot,''))) IN ('МУЖ','М')) ORDER BY oi.created_at,oi.id LIMIT 1300",
  "MALE_FULL_MOVEMENT_HISTORY": "SELECT m.id,m.inventory_source AS source,m.product_id,m.variant_id,m.product_name_snapshot,m.gender_snapshot,m.color_snapshot,m.material_snapshot,m.length_snapshot,m.size_snapshot,m.movement_type,m.quantity_delta AS delta,m.quantity_after AS after,m.reference_type,m.reference_id,m.created_at,m.comment FROM inventory_movements m WHERE m.variant_id IN (SELECT v.id FROM catalog_variants v JOIN catalog_products p ON p.id=v.product_id WHERE (UPPER(COALESCE(p.name,'')) LIKE '%БАЯН%' OR UPPER(COALESCE(p.name,'')) LIKE '%НӘЗІК%' OR UPPER(COALESCE(p.name,'')) LIKE '%НАЗЫК%' OR UPPER(COALESCE(p.name,'')) LIKE '%НАЗИК%') AND UPPER(TRIM(COALESCE(v.gender,''))) IN ('МУЖ','М','MALE')) OR ((UPPER(COALESCE(m.product_name_snapshot,'')) LIKE '%БАЯН%' OR UPPER(COALESCE(m.product_name_snapshot,'')) LIKE '%НӘЗІК%' OR UPPER(COALESCE(m.product_name_snapshot,'')) LIKE '%НАЗЫК%') AND UPPER(TRIM(COALESCE(m.gender_snapshot,''))) IN ('МУЖ','М')) ORDER BY m.variant_id,m.created_at,m.id LIMIT 1500",
  "MALE_FULL_STOCK_CHECKS": "SELECT c.id,c.inventory_source AS source,c.variant_id,c.expected_quantity,c.counted_quantity,c.difference_quantity,c.reserved_quantity,c.check_type,c.reference_type,c.reference_id,c.checked_at,c.checked_by FROM inventory_stock_checks c WHERE c.variant_id IN (SELECT v.id FROM catalog_variants v JOIN catalog_products p ON p.id=v.product_id WHERE (UPPER(COALESCE(p.name,'')) LIKE '%БАЯН%' OR UPPER(COALESCE(p.name,'')) LIKE '%НӘЗІК%' OR UPPER(COALESCE(p.name,'')) LIKE '%НАЗЫК%' OR UPPER(COALESCE(p.name,'')) LIKE '%НАЗИК%') AND UPPER(TRIM(COALESCE(v.gender,''))) IN ('МУЖ','М','MALE')) ORDER BY c.variant_id,c.checked_at,c.id LIMIT 800",
  "MALE_FULL_STOCKTAKES": "SELECT st.id,st.inventory_source AS source,st.variant_id,st.opening_quantity,st.opening_reserved_quantity,st.baseline_quantity,st.counted_quantity,st.applied_quantity,st.status AS line_status,st.counted_at,st.updated_at,ss.status AS session_status,ss.completed_at,ss.created_by FROM inventory_stocktake_items st LEFT JOIN inventory_stocktake_sessions ss ON ss.id=st.session_id WHERE st.variant_id IN (SELECT v.id FROM catalog_variants v JOIN catalog_products p ON p.id=v.product_id WHERE (UPPER(COALESCE(p.name,'')) LIKE '%БАЯН%' OR UPPER(COALESCE(p.name,'')) LIKE '%НӘЗІК%' OR UPPER(COALESCE(p.name,'')) LIKE '%НАЗЫК%' OR UPPER(COALESCE(p.name,'')) LIKE '%НАЗИК%') AND UPPER(TRIM(COALESCE(v.gender,''))) IN ('МУЖ','М','MALE')) ORDER BY st.variant_id,st.updated_at,st.id LIMIT 1200",
  "MALE_OPERATION_EVIDENCE": "SELECT e.id,e.variant_id,e.inventory_source,e.operation_type,e.operation_reference,e.tracked_physical_before,e.confirmed_operation_quantity,e.unexplained_quantity,e.confirmed_by,e.occurred_at FROM inventory_operation_evidence e WHERE e.variant_id IN (SELECT v.id FROM catalog_variants v JOIN catalog_products p ON p.id=v.product_id WHERE (UPPER(COALESCE(p.name,'')) LIKE '%БАЯН%' OR UPPER(COALESCE(p.name,'')) LIKE '%НӘЗІК%' OR UPPER(COALESCE(p.name,'')) LIKE '%НАЗЫК%' OR UPPER(COALESCE(p.name,'')) LIKE '%НАЗИК%') AND UPPER(TRIM(COALESCE(v.gender,''))) IN ('МУЖ','М','MALE')) ORDER BY e.variant_id,e.occurred_at LIMIT 500",
  "MALE_SIMILAR_PRODUCT_NONMALE_MOVEMENTS": "SELECT p.name AS product,v.id AS variant_id,v.gender,v.color,v.material,v.length,v.size_label AS size,m.inventory_source,m.movement_type,COUNT(*) AS ops,SUM(m.quantity_delta) AS total_delta,MIN(m.created_at) AS first,MAX(m.created_at) AS last FROM catalog_variants v JOIN catalog_products p ON p.id=v.product_id JOIN inventory_movements m ON m.variant_id=v.id WHERE (UPPER(COALESCE(p.name,'')) LIKE '%БАЯН%' OR UPPER(COALESCE(p.name,'')) LIKE '%НӘЗІК%' OR UPPER(COALESCE(p.name,'')) LIKE '%НАЗЫК%' OR UPPER(COALESCE(p.name,'')) LIKE '%НАЗИК%') GROUP BY v.id,m.inventory_source,m.movement_type ORDER BY p.name,v.id,m.inventory_source,m.movement_type LIMIT 500",
  "OPERATIONS_STATUS": "SELECT COALESCE(status,'') AS status,COALESCE(operation_type,'') AS operation_type,COUNT(*) AS n,MIN(created_at) AS earliest,MAX(created_at) AS latest FROM inventory_operations GROUP BY COALESCE(status,''),COALESCE(operation_type,'') ORDER BY n DESC LIMIT 80",
  "FAILED_INVENTORY_OPERATIONS": "SELECT operation_id,operation_type,source_type,target_source_type,status,created_at,completed_at,SUBSTR(COALESCE(error_message,''),1,500) AS error_message,SUBSTR(COALESCE(comment,''),1,200) AS comment FROM inventory_operations WHERE COALESCE(status,'') NOT IN ('completed','success','applied') OR COALESCE(error_message,'')<>'' ORDER BY created_at DESC LIMIT 200",
  "FAILED_CRITICAL_OPERATIONS": "SELECT operation_type,status,step,target_type,target_id,target_ref,SUBSTR(COALESCE(last_error,''),1,300) AS last_error,created_at,updated_at FROM critical_operations WHERE (COALESCE(last_error,'')<>'' OR COALESCE(status,'') IN ('failed','error','blocked')) AND (operation_type LIKE '%inventory%' OR operation_type LIKE '%arrival%' OR operation_type LIKE '%stock%' OR operation_type LIKE '%order%') ORDER BY created_at DESC LIMIT 150",
  "RECENT_ACTIVE_RESERVES_NO_POSITIVE_MOVEMENTS": "WITH o AS (SELECT r.inventory_source AS source,r.variant_id,r.order_id,r.quantity,o.order_date,o.created_at AS order_created_at FROM inventory_reservations r JOIN orders o ON o.id=r.order_id WHERE r.status='active' AND r.variant_id IS NOT NULL AND o.order_date>='2026-10-01' AND COALESCE(o.shipping_status,'not_sent')<>'sent' AND COALESCE(o.order_status,'active')='active'), a AS (SELECT source,variant_id,COUNT(*) AS order_lines,SUM(quantity) AS reserved_units,MIN(order_date) AS earliest_order,MAX(order_date) AS latest_order FROM o GROUP BY source,variant_id) SELECT a.source,a.variant_id,p.name AS product,v.gender,v.color,v.material,v.length,v.size_label AS size,COALESCE(s.quantity,0) AS physical,a.reserved_units,a.order_lines,a.earliest_order,a.latest_order,(SELECT COUNT(*) FROM inventory_movements m WHERE m.variant_id=a.variant_id AND m.inventory_source=a.source AND m.quantity_delta>0) AS any_positive_movements,(SELECT COUNT(*) FROM inventory_stock_checks c WHERE c.variant_id=a.variant_id AND c.inventory_source=a.source AND c.counted_quantity>0) AS any_positive_counts FROM a JOIN catalog_variants v ON v.id=a.variant_id JOIN catalog_products p ON p.id=v.product_id LEFT JOIN inventory_stock s ON s.variant_id=a.variant_id AND s.inventory_source=a.source WHERE COALESCE(s.quantity,0)<=0 ORDER BY a.latest_order DESC,a.source,a.variant_id LIMIT 300",
  "PRODUCT_VARIANT_MERGES": "SELECT old_variant_id,keeper_variant_id,reason,merged_at FROM catalog_identity_variant_merges WHERE old_variant_id IN (SELECT v.id FROM catalog_variants v JOIN catalog_products p ON p.id=v.product_id WHERE (UPPER(COALESCE(p.name,'')) LIKE '%БАЯН%' OR UPPER(COALESCE(p.name,'')) LIKE '%НӘЗІК%' OR UPPER(COALESCE(p.name,'')) LIKE '%НАЗЫК%' OR UPPER(COALESCE(p.name,'')) LIKE '%НАЗИК%')) OR keeper_variant_id IN (SELECT v.id FROM catalog_variants v JOIN catalog_products p ON p.id=v.product_id WHERE (UPPER(COALESCE(p.name,'')) LIKE '%БАЯН%' OR UPPER(COALESCE(p.name,'')) LIKE '%НӘЗІК%' OR UPPER(COALESCE(p.name,'')) LIKE '%НАЗЫК%' OR UPPER(COALESCE(p.name,'')) LIKE '%НАЗИК%')) ORDER BY merged_at LIMIT 300"
};
const run=(sql)=>{
 const stmt=sql.trim().toUpperCase();
 if(!/^(SELECT|WITH)\b/.test(stmt)||/\b(UPDATE|DELETE|INSERT|ALTER|DROP|CREATE|REPLACE|PRAGMA|ATTACH|DETACH|VACUUM)\b/.test(stmt))throw Error('SELECT-only gate rejected');
 const stdout=execFileSync('npx',['wrangler','d1','execute','orders_db_prod','--remote','--config','wrangler.jsonc','--command',sql.trim(),'--json'],{encoding:'utf8',maxBuffer:30*1024*1024,timeout:120000});
 const parsed=JSON.parse(stdout);
 if(parsed.some(x=>x.success!==true))throw Error('D1 SELECT failure');
 return parsed.flatMap(x=>x.results||[]);
};
const report={};
for(const [name,sql] of Object.entries(queries)){
 const rows=run(sql);
 report[name]=rows;
 console.log('== '+name+' count='+rows.length+' ==');
 if(rows.length<=200)console.log('RESULT '+name+' '+JSON.stringify(rows));
 else console.log('RESULT '+name+' first='+JSON.stringify(rows.slice(0,35))+' last='+JSON.stringify(rows.slice(-15)));
}
writeFileSync('male-sku-provenance-20261019.json',JSON.stringify(report,null,2));
console.log('MALE_SKU_PROVENANCE_READONLY_COMPLETE');